head.script:
/* 프로그램ID */
scwin.pgmId = 'PGJ151M02';

/* 회원id */
scwin.lgnMbr = '';

/* 검색조건 */
scwin.param;

/* 페이즈 크기 */
scwin.pageSize;

/* 이전메뉴정보 */
scwin.menuNm='';
scwin.prevPgmId= '';
scwin.pageNum = '';

/* 헤더정렬 */
scwin.headers;
scwin.sortOrder = 0;
scwin.sortOrderId = "csNo";

/**
 * onPageLoad시 검색조건 데이터로 상세조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.22.   나해준       [NELS]최초 생성
 *  2025.12.26.   공태은       [25A-PGJ-0053] 나의경매 자주쓰는검색 화면에서 페이지 이동시 검색조건이 초기화되는 현상 수정
 * ============= ============ ==========================
 */
scwin.onpageload = function() {
    scwin.param = $p.getParameter("param");
    scwin.pgmId = scwin.param.srchInfo.pgmId;
    scwin.prevPgmId = scwin.param.srchInfo.pgmId;
    scwin.menuNm = scwin.param.srchInfo.menuNm;
    scwin.pageNum = scwin.param?.prevInfo?.pageNum || 1;

    //자주쓰는검색
    const sideDvsCd = scwin.param.srchInfo ?. sideDvsCd;
    let prevMenuNm = '';
    if (sideDvsCd == "3"){
        scwin.menuNm = "자주쓰는검색";
        prevMenuNm = "나의경매";
        wfm_side.setSrc("../common/sideMenu/side006.xml");
    }else{
        scwin.menuNm = "물건상세검색";
        prevMenuNm = "경매물건";
    }

    tbx_titleNm.setValue(scwin.menuNm);
    tbx_prevTitleNm.setValue(prevMenuNm);
    tbx_subTitleNm.setValue(scwin.menuNm);

    /* 메뉴 */
    if(!scutilo.isEmpty(scwin.pgmId)){
       $p.main().wfm_mainFrame.scope.wfm_side.scope.scwin.menuFocus(scwin.pgmId.slice(0,6));
    }

    if (scutilo.isEmpty(pgjUtil.getCookie('pageCnt'))) { //페이지 크기 설정 바꿔야함 TO-DO
        scwin.pageSize =10;
        sbx_pageSize.setValue('10');
    } else {
        scwin.pageSize = Number(pgjUtil.getCookie('pageCnt'));
        sbx_pageSize.setValue(pgjUtil.getCookie('pageCnt'));
    }
    dma_srchGdsDtlSrchInfo.setJSON(scwin.param.srchInfo);
    scwin.gdsDtlSrchMain(true, scwin.pageSize);
};

scwin.onpageunload = function(isFirst,pagaSize) {

};

//웹접근성으로 인한 title제공 수정
scwin.titleFormatter = function(){
    return "";
}


/**
 * 페이지 설정후 데이터 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.22.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.gdsDtlSrchMain = function(isFirst,pagaSize) {
    /* 최초 조회 여부 */
    if (isFirst) {
        dma_pageInfo.set("totalYn", "Y");
    } else {
        dma_pageInfo.set("totalYn", "N");
    }

    /* 페이지 사이즈 셋팅 */
    dma_pageInfo.set("pageNo", scwin.pageNum);
    dma_pageInfo.set("pageSize", pagaSize);
    com.executeSubmission(sbm_selectGdsDtlSrch);
}

/**
 * 페이지 번호 클릭시 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.22.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.pgl_gdsDtlSrchPage_onviewchange = function(info) {

    dma_pageInfo.set( "pageNo" , info.newSelectedIndex );
    dma_pageInfo.set( "bfPageNo",info.oldSelectedIndex );
    scwin.pageNum = info.newSelectedIndex;
    scwin.gdsDtlSrchMain(false, scwin.pageSize);//조회처리
};

/**
 * 데이터 조회후 데이터 셋팅
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.22.   나해준       [NELS]최초 생성
 *  2025.12.26.   공태은       [25A-PJG-0052] 기일별 검색 목록 화면에서 상세 화면에서 목록화면으로 이동시 스크롤바 유지되도록 개선
 * ============= ============ ==========================
 */
scwin.sbm_selectGdsDtlSrch_submitdone = function(e) {

    const topScroll = scwin.param.srchInfo.srchRowIndex;

    // 스크롤 위치 정보가 없는 경우 최상단, 있으면 해당하는 위치로 이동
    if(!scutilo.isEmpty(topScroll)){
        document.body.scrollTop = topScroll;
    }else{
        document.body.scrollTop = 0;
    }

const ipcheck = e.responseJSON.data.ipcheck; //로봇탐지
if(ipcheck){
    /* 메인상단 검색조건 셋팅 시작 */

    if(dma_pageInfo.get("totalYn") == "Y") {
        let genCnt = 0;
        let param = scwin.param.srchInfo;
        let cortStDvs = param.cortStDvs;
        if (!scutilo.isEmpty(cortStDvs) && "1" == cortStDvs) {
            gna_srhcTitle.insertChild(genCnt)
            gna_srhcTitle.getChild(genCnt, "spn_srchTitle").setValue("법원")
            if (scutilo.isEmpty(param.cortOfcCd)) {
                gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue("전체")
            } else {
                gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue(pgjUtil.getCortOfcNm("O",param.cortOfcCd))
            }
            genCnt++
        } else if (!scutilo.isEmpty(cortStDvs) && "2" == cortStDvs) {
            gna_srhcTitle.insertChild(genCnt)
            gna_srhcTitle.getChild(genCnt, "spn_srchTitle").setValue("소재지")
            if (scutilo.isEmpty(param.mvprpDspslPlcAdongSdCd)) {
                gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue("")
            } else {
                let stNm =""
                stNm = pgjUtil.getSdNm(param.mvprpDspslPlcAdongSdCd,"O");
                if (!scutilo.isEmpty(param.mvprpDspslPlcAdongSggCd)) {
                    stNm += ` ${pgjUtil.getSggNm(param.mvprpDspslPlcAdongSdCd,param.mvprpDspslPlcAdongSggCd,"O")}`;
                }
                if(!scutilo.isEmpty(param.mvprpDspslPlcAdongEmdCd)) {
                    stNm += ` ${pgjUtil.getEmdNm(param.mvprpDspslPlcAdongSdCd,param.mvprpDspslPlcAdongSggCd,param.mvprpDspslPlcAdongEmdCd,"O")}`
                }
                gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue(stNm)
            }
            genCnt++
        } else if (!scutilo.isEmpty(cortStDvs) && "3" == cortStDvs) {
            gna_srhcTitle.insertChild(genCnt)
            gna_srhcTitle.getChild(genCnt, "spn_srchTitle").setValue("소재지")
            if (scutilo.isEmpty(param.rdDspslPlcAdongSdCd)) {
                gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue("")
            } else {
                let stNm =""
                stNm = pgjUtil.getSdNm(param.rdDspslPlcAdongSdCd,"R")
                if (!scutilo.isEmpty(param.rdDspslPlcAdongSggCd)) {
                    stNm +=` ${pgjUtil.getSggNm(param.rdDspslPlcAdongSdCd,param.rdDspslPlcAdongSggCd,"R")}`
                }
                if(!scutilo.isEmpty(param.rdDspslPlcAdongEmdCd)) {
                    stNm += ` ${pgjUtil.getNewAddrRdNm(param.rdDspslPlcAdongSdCd,param.rdDspslPlcAdongSggCd,param.rdDspslPlcAdongEmdCd,"R")}`
                }
                gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue(stNm)
            }
            genCnt++
        }
        if (!scutilo.isEmpty(param.jdbnCd)) { //집행관 사무소 부서
            gna_srhcTitle.insertChild(genCnt)
            gna_srhcTitle.getChild(genCnt, "spn_srchTitle").setValue("부서")
            if (!scutilo.isEmpty(param.cortOfcCd) && param.cortOfcCd == "") {
                gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue("")
            } else {
                gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue(pgjUtil.getDeptNm(param.cortOfcCd,param.jdbnCd))
            }
            genCnt++
        }
        //사건번호
        if (!scutilo.isEmpty(param.csNo)) {
            gna_srhcTitle.insertChild(genCnt)
            gna_srhcTitle.getChild(genCnt, "spn_srchTitle").setValue("사건번호")
            gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue(param.mvprpCsNo)
            genCnt++
        }
        //매각기일
        if (!scutilo.isEmpty(param.dspslDxdyYmd) || (!scutilo.isEmpty(param.bidBgngYmd) && param.bidBgngYmd.length ==8)) {
            let printDxDy ="";
            gna_srhcTitle.insertChild(genCnt)
            gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue(param.mvprpCsNo)
            gna_srhcTitle.getChild(genCnt, "spn_srchTitle").setValue("매각기일");
            if (!scutilo.isEmpty(param.dspslDxdyYmd)) {
                printDxDy = scdateo.getFmtDate(param.dspslDxdyYmd,'.');
                if(!scutilo.isEmpty(param.fstDspslHm)) printDxDy +=` (${scwin.timeFormat(param.fstDspslHm)}`
                if(!scutilo.isEmpty(param.scndDspslHm)) printDxDy +=`,${scwin.timeFormat(param.scndDspslHm)}`
                if(!scutilo.isEmpty(param.thrdDspslHm)) printDxDy +=`,${scwin.timeFormat(param.thrdDspslHm)}`
                if(!scutilo.isEmpty(param.fothDspslHm)) printDxDy +=`,${scwin.timeFormat(param.fothDspslHm)}`
                if(!scutilo.isEmpty(param.dspslPlcNm)) printDxDy +=`${param.dspslPlcNm})`

            } else {
                printDxDy = `${scdateo.getFmtDate(param.bidBgngYmd,".")} ~ ${scdateo.getFmtDate(param.bidEndYmd,".")}`
            }
            gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue(printDxDy)
            genCnt++
        }
        if (!scutilo.isEmpty(param.mvprpArtclKnd)) { //동산 물품종류
            gna_srhcTitle.insertChild(genCnt)
            gna_srhcTitle.getChild(genCnt, "spn_srchTitle").setValue("물품종류")
            let kndNm = pgjUtil.getMyAuctnArtclKndLst().filter(r =>r.code === param.mvprpArtclKnd).map(r=>{
                return r.name;
            }) ?. [0]
            gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue(kndNm)
            genCnt++
        }

        if (!scutilo.isEmpty(param.maeMokmulNm)) { //동산 물품명
            gna_srhcTitle.insertChild(genCnt)
            gna_srhcTitle.getChild(genCnt, "spn_srchTitle").setValue("물품명")
            gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue(param.maeMokmulNm)
            genCnt++
        }

        if (!scutilo.isEmpty(param.mvrpDspslPlcTyp)) { //동산 매각장소유형
            gna_srhcTitle.insertChild(genCnt)
            gna_srhcTitle.getChild(genCnt, "spn_srchTitle").setValue("매각장소유형")
            let typNm = pgjUtil.getMvprpDspslPlcTypLst().filter(r =>r.code === param.mvrpDspslPlcTyp).map(r=>{
                return r.name;
            }) ?. [0]
            gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue(typNm)
            genCnt++
        }

        if (!scutilo.isEmpty(param.aeeEvlAmtMin) || !scutilo.isEmpty(param.aeeEvlAmtMax) ) { //감정평가액 시작
            gna_srhcTitle.insertChild(genCnt)
            gna_srhcTitle.getChild(genCnt, "spn_srchTitle").setValue("감정평가액")
            let aeeEvlAmt =""
            if (param.aeeEvlAmtMin == param.aeeEvlAmtMax) {
                if (param.aeeEvlAmtMin.length == 8) {
                    aeeEvlAmt = `${param.aeeEvlAmtMin.substring(0,1)}천만원`
                } else if (param.aeeEvlAmtMin.length == 9) {
                    aeeEvlAmt = `${param.aeeEvlAmtMin.substring(0,1)}억`
                    if (param.aeeEvlAmtMin.substring(1,2) == "5") {
                        aeeEvlAmt += `${param.aeeEvlAmtMin.substring(1,2)}천만원`
                    } else {
                        aeeEvlAmt += "원";
                    }
                } else if (param.aeeEvlAmtMin.length == 10) {
                    aeeEvlAmt = `${param.aeeEvlAmtMin.substring(0,2)}억원`
                }
            } else {//앞 뒤 금액 값이 다른 경우
                if (!scutilo.isEmpty(param.aeeEvlAmtMin) && param.aeeEvlAmtMin.length == 8) {
                    aeeEvlAmt = `${param.aeeEvlAmtMin.substring(0,1)}천만원 이상`
                    if (param.aeeEvlAmtMax !="1000000001" ) aeeEvlAmt += "~"
                } else if (!scutilo.isEmpty(param.aeeEvlAmtMin) && param.aeeEvlAmtMin.length == 9) {
                    aeeEvlAmt = `${param.aeeEvlAmtMin.substring(0,1)}억`
                    if (param.aeeEvlAmtMin.substring(1,2) == "5") {
                        aeeEvlAmt += `${param.aeeEvlAmtMin.substring(1,2)}천만원 이상`
                    } else {
                        aeeEvlAmt += "원 이상";
                    }
                    if (param.aeeEvlAmtMax !="1000000001" ) aeeEvlAmt += "~"
                } else if (!scutilo.isEmpty(param.aeeEvlAmtMin) && param.aeeEvlAmtMin.length == 10) {
                    aeeEvlAmt = `${param.aeeEvlAmtMin.substring(0,2)}억원 이상`
                }
                if (!scutilo.isEmpty(param.aeeEvlAmtMax) && param.aeeEvlAmtMax.length == 8) {
                    aeeEvlAmt += `${param.aeeEvlAmtMax.substring(0,1)}천만원 이하`
                } else if (!scutilo.isEmpty(param.aeeEvlAmtMax) && param.aeeEvlAmtMax.length == 9) {
                    aeeEvlAmt += `${param.aeeEvlAmtMax.substring(0,1)}억`;
                    if (param.aeeEvlAmtMax.substring(1,2) == "5") {
                        aeeEvlAmt += `${param.aeeEvlAmtMax.substring(1,2)}천만원 이하`
                    } else {
                        aeeEvlAmt += "원 이하";
                    }
                } else if (!scutilo.isEmpty(param.aeeEvlAmtMax) && param.aeeEvlAmtMax.length == 10) {
                    aeeEvlAmt += `${param.aeeEvlAmtMax.substring(0,2)}억원 이하`
                }
            }
            gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue(aeeEvlAmt);
            genCnt++
        }

        if (!scutilo.isEmpty(param.lwsDspslPrcMin) || !scutilo.isEmpty(param.lwsDspslPrcMax)) {//최저 매가각가격
            gna_srhcTitle.insertChild(genCnt)
            gna_srhcTitle.getChild(genCnt, "spn_srchTitle").setValue("최저매각가격")
            let lwsPrc =""
            if (param.lwsDspslPrcMin == param.lwsDspslPrcMax) {
                if (param.lwsDspslPrcMin.length == 8){
                    lwsPrc = `${param.lwsDspslPrcMin.substring(0,1)}천만원`
                } else if (param.lwsDspslPrcMin.length == 9) {
                    lwsPrc = `${param.lwsDspslPrcMin.substring(0,1)}억`;
                    if (param.lwsDspslPrcMin.substring(1,2) == "5") {
                        lwsPrc += `${param.lwsDspslPrcMin.substring(1,2)}천만원`
                    } else {
                        lwsPrc += "원";
                    }
                } else if (param.lwsDspslPrcMin.length == 10) {
                    lwsPrc = `${param.lwsDspslPrcMin.substring(0,2)}억원`
                }
            } else {//앞 뒤 금액 값이 다른 경우
                if (!scutilo.isEmpty(param.lwsDspslPrcMin) && param.lwsDspslPrcMin.length == 8) {
                    lwsPrc = `${ param.lwsDspslPrcMin.substring(0,1)}천만원 이상`
                    if ( param.lwsDspslPrcMax == "1000000001") lwsPrc += "~"
                } else if (!scutilo.isEmpty(param.lwsDspslPrcMin) && param.lwsDspslPrcMin.length == 9) {
                    lwsPrc = `${param.lwsDspslPrcMin.substring(0,1)}억`
                    if (param.lwsDspslPrcMin.substring(1,2) == "5") {
                        lwsPrc += `${param.lwsDspslPrcMin.substring(1,2)}천만원 이상`;
                    } else {
                        lwsPrc += "원 이상";
                    }
                    if (param.lwsDspslPrcMax == "1000000001") lwsPrc += "~"
                }else if (!scutilo.isEmpty(param.lwsDspslPrcMin) && param.lwsDspslPrcMin.length == 10) {
                    lwsPrc = `${param.lwsDspslPrcMin.substring(0,2)}억원 이상`;
                }
                if (!scutilo.isEmpty(param.lwsDspslPrcMax) && param.lwsDspslPrcMax.length == 8){
                    lwsPrc += `${param.lwsDspslPrcMax.substring(0,1)}천만원 이하`;
                }else if (!scutilo.isEmpty(param.lwsDspslPrcMax) && param.lwsDspslPrcMax.length == 9){
                    lwsPrc += `${param.lwsDspslPrcMax.substring(0,1)}억`
                    if(param.lwsDspslPrcMax.substring(1,2) == "5") {
                        lwsPrc += `${param.lwsDspslPrcMax.substring(1,2)}천만원 이하`;
                    }else{
                        lwsPrc += "원 이하";
                    }
                }else if (!scutilo.isEmpty(param.lwsDspslPrcMax) && param.lwsDspslPrcMax.length == 10) {
                    lwsPrc += `${param.lwsDspslPrcMax.substring(0,2)}억원 이하`;
                }
            }
            gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue(lwsPrc);
            genCnt++
        }
        if (!scutilo.isEmpty(dma_pageInfo.get("totalCnt"))) {
            gna_srhcTitle.insertChild(genCnt)
            gna_srhcTitle.getChild(genCnt, "spn_srchTitle").setValue(`총 물건수`);

            if (dma_pageInfo.get("totalCnt") !== '0') {
                gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue(`${dma_pageInfo.get("totalCnt")}건`);
                grp_rletPageInfo.show('');
            } else {
                gna_srhcTitle.getChild(genCnt, "spn_srchCtt").setValue(` 0건`);
                grp_rletPageInfo.hide();
            }
        }
            gna_srhcTitle.getChild(genCnt,"spn_srchBar").setValue("");//검색조건 타이틀 끝
        }

        //=================================================검색조건 끝
        const lst = pgjUtil.getMvprpDspslPlcTypLst();
        for (let i=0; i<dlt_srchResult.getTotalRow(); i++) {
            let typeNm = ""
            let cd = dlt_srchResult.getCellData(i, "mvrPlaceTypcd");
            typeNm = lst.filter(r=> r.code === cd).map(r=>{
                return r.name
                }) ?. [0]
            dlt_srchResult.setCellData(i, 'mvrPlaceTypcdNm', typeNm)
        }

        //헤더 정렬 아이콘 생성
        scwin.headers = [
            { id:"csNo", val:"사건번호"},
            { id:"aeeEvlAmt", val:"감정평가액"},
            { id:"pbancLwsDspslPrc", val:"최저매각가격"},
            { id:"dspslDxdyYmd", val:"매각부서<br>매각기일"}];
        let sortImage = "";
        scwin.headers.forEach(t=>{
            sortImage = "<text>";
            sortImage += t.val+"</text>";
            sortImage += `<a href="#" onclick="headerSortSch('${t.id}')"><img src="/pgj/cm/images/contents/ic_sort_up.gif" style="width:12px;margin:5px;" alt="오름" /></a></div>`;
            if(t.id == "pbancLwsDspslPrc"){
               sortImage += "<br>(단위:원)";
            }
            //정렬인 경우
            if(scwin.sortOrderId === t.id){
                if(scwin.sortOrder === 1){
                    sortImage = sortImage.replaceAll('ic_sort_up', 'ic_sort_up_s');
                } else if(scwin.sortOrder === -1){
                    sortImage = sortImage.replaceAll('ic_sort_up', 'ic_sort_down_s');
                }
            }
            grd_gdsDtlSrchResult.setHeaderValue(t.id, sortImage, false);
        });

        //페이징 처리
        if(String(dma_pageInfo.get("totalCnt")) !== '0') {
            grp_rletPageInfo.show("");
            spn_totalCnt.setValue(dma_pageInfo.get("totalCnt"))
            scutilo.setPagingInfo(dma_pageInfo,pgl_gdsDtlSrchPage,grd_gdsDtlSrchResult);
            pgl_gdsDtlSrchPage.setValue(scwin.pageNum);
        } else {
            grp_rletPageInfo.hide();
        }
    } else {
        scutilo.showMsg(scglblo.MSG.ERROR,e.responseJSON.message,()=>{
			$p.url("/pgj/ui/pgj100/PGJ111M01.xml");
		});
    }

};

/**
 * 헤더 정렬
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.21.09.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
function headerSortSch(id) {
    let headerId = id;
    let lafjOrderBy = "order by ";
    let sortImage = "";

    //초기화
    scwin.headers.forEach(t=>{
        sortImage = grd_gdsDtlSrchResult.getHeaderValue(t.id);
        sortImage = sortImage.replaceAll('ic_sort_up_s', 'ic_sort_up');
        sortImage = sortImage.replaceAll('ic_sort_down_s', 'ic_sort_up');
        grd_gdsDtlSrchResult.setHeaderValue(t.id, sortImage, false);
    });

    //정렬셋팅
    sortImage = grd_gdsDtlSrchResult.getHeaderValue(id);
    if(scwin.sortOrderId === id){
        if(scwin.sortOrder === 1){
            lafjOrderBy += String(headerId + " desc");
            sortImage = sortImage.replaceAll('ic_sort_up', 'ic_sort_down_s');
            scwin.sortOrder = -1;
        } else if(scwin.sortOrder === -1){
            lafjOrderBy += String(headerId + " asc");
            sortImage = sortImage.replaceAll('ic_sort_up', 'ic_sort_up_s');
            scwin.sortOrder = 1;
        } else { //0
            lafjOrderBy += String(headerId + " asc");
            sortImage = sortImage.replaceAll('ic_sort_up', 'ic_sort_up_s');
            scwin.sortOrder = 1;
        }
    } else {
        lafjOrderBy += String(headerId + " asc");
        sortImage = sortImage.replaceAll('ic_sort_up', 'ic_sort_up_s');
        scwin.sortOrder = 1;
        scwin.sortOrderId = id;
    }

    grd_gdsDtlSrchResult.setHeaderValue(id, sortImage, false);
    dma_srchGdsDtlSrchInfo.set("lafjOrderBy", lafjOrderBy);
    scwin.gdsDtlSrchMain(false, scwin.pageSize);//조회처리
};

