/**
 *
 * 그리드 담당계 툴팁 key 제어하기위한 이벤트(접근성)
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.09.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 *
 */
scwin.grd_gdsDtlSrchResult_onkeydown = function(e) {
    var _colId = grd_gdsDtlSrchResult.getFocusedColumnID();
    if(_colId == "jpDeptNm" && e.key == 'Enter'){

        //tooltip 상태값을 구하여 표시하기
        var tooltip = $(".w2grid_tooltip").css("display");

        //마우스 오버를 못한 경우, 직접 툴팁 이벤트를 실행하여 생성
         if(tooltip == "undefined" || tooltip == null || tooltip == ""){
            let rowIndex = dlt_srchResult.getRowPosition();
            const tel = dlt_srchResult.getCellData(rowIndex, "tel");
            const giil = `${scdateo.getFmtDate(dlt_srchResult.getCellData(rowIndex, "giil"),".")} ${scwin.timeFormat(dlt_srchResult.getCellData(rowIndex,"hh"))} `;
            txt =`<div class="toolTipText">
                <span>·<text class="mr5" style="color:#6798FD; width:16px;">전화번호</text>${tel}</span><br/>
                <span>·<text class="mr5" style="color:#6798FD; width:16px;">매각기일</text>${giil}</span></div>`;

            //툴팁 좌표 계산해서 표시(wframe: left(732) top(418))
            const winW = window.innerWidth/2;
            const winH = window.innerHeight/2;
            let colIndex = grd_gdsDtlSrchResult.getColumnIndex("jpDeptNm");
            var top = grd_gdsDtlSrchResult.getPosition("top") + winH;
            var left = winW + winW/2;
            grd_gdsDtlSrchResult.showTooltip(left, top, txt);

            $(".w2grid_tooltip").css("display", "none");
            setTimeout(function(){
                $(".w2grid_tooltip").css("display", "block");
            }, 500);


        //툴팁 엘리먼트가 생성되고 표시가 안된 경우
        } else if(tooltip == "none"){
            setTimeout(function(){
                $(".w2grid_tooltip").css("display", "block");
            }, 500);

        //툴팁 엘리먼트가 생성되고 표시가 된 경우
        } else {
            $(".w2grid_tooltip").css("display", "none");
        }
    }
};

/**
 * 쉘 클릭 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.11.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.grd_gdsDtlSrchResult_oncellclick = function(row,col,colId) {
    var _colId = grd_gdsDtlSrchResult.getFocusedColumnID();
    if (_colId == "btnMap") {

        /********* Popup Settings *********/
        const winW = window.innerWidth;
        const winH = window.innerHeight;

        /* default popup size */
        const popupW = winW - 300;
        const popupH = winH - 100;

        const popupX = (winW/2) - (popupW/2);
        const popupY = (winH/2) - (popupH/2);

        const options = {
            id: "gdsMap",
            type: "browser",
            popupName: "지도",
            top:popupY,
            left:popupX,
            width:popupW,
            height:popupH,
            modal: false
        };

        paramObj = {};
        paramObj.pgmId = "PGJ151M02";
        paramObj.info = {
            csNo : dlt_srchResult.getCellData(row, 'saNo'),
            cortOfcCd : dlt_srchResult.getCellData(row, 'boCd'),
            dspslGdsSeq : dlt_srchResult.getCellData(row, 'maemulSer'),
            objctSeq : dlt_srchResult.getCellData(row, 'mokmulSer'),
            cortOfcNm : dlt_srchResult.getCellData(row, 'jiwonNm'),
        };

        com.win.openPopup("/pgj/ui/pgj100/PGJ152F00.xml",options,paramObj);

    } else if(_colId == "notifyTypcd"){
        const mulBigo = dlt_srchResult.getCellData(row, 'mulBigo');
        if(!scutilo.isEmpty(mulBigo)) {
            scutilo.showMsg("특이사항", mulBigo);

            //특이사항 창크기 조정
            setTimeout(function(){
                const el = document.querySelector('.messagebox');
                const els = el.querySelectorAll('textarea'); //tbx_message
                const message = els[0];
                const elId = document.getElementById(el.id);
                const messageId = document.getElementById(message.id);
                elId.style.width = '550px';
                elId.style.height = '350px';
                messageId.style.height = '90%';
            }, 10);
            $("#_modal").css("pointer-events", "none");
        }
    }
};

/**
 *  이전페이지 이동 버튼 기능
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.11.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_prevPage_onclick = function(e) {

    let dtlSrchParam = {
        prevInfo: {
            prevPgmId: scwin.prevPgmId
        },
        srchInfo: scwin.param.srchInfo
    }

    if (scwin.pgmId === 'PGJ151F01') {
        $w.local.setItem('dtlSrchParam', JSON.stringify(dtlSrchParam));
        $p.url(`/pgj/ui/pgj100/PGJ151F00.xml`);
    } else if (scwin.pgmId === 'PGJ153M01') {
        $w.local.setItem('dtlSrchParam', encodeURI(JSON.stringify(dtlSrchParam)));
        $p.url(`/pgj/ui/pgj100/PGJ153F00.xml`);
    } else if (scwin.pgmId === 'PGJ195M02') {
        $p.url("/pgj/ui/pgj100/PGJ195M00.xml");
    } else if (scwin.pgmId ==='mainUsg') {
        $p.url(`/pgj/ui/pgj100/PGJ111M01.xml`);
    }
};

/**
 *
 * 그리드 사건 번호 Format 메서드
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.07.03.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.csNoFormat = function(data, formattedData, rowIndex, colIndex){
    let csLst = data.split("</br>")
	let result1 = `<div><a href="#" onclick="moveCsDtlPage(${rowIndex})">${csLst[0]}</a><br>`
	let result2 = ""
	if (csLst.length > 1) {
		csLst.forEach( (r,i) => {
			if (i != 0 ) result2 += `<text>${r}</text><br>`
		})
	}
    return result1 + `${result2}</div>`;
}


/**
 *
 * 물건 상세 페이지 이동
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.07.03.   나해준       [NELS]최초 생성
 *  2025.12.26.   공태은       [25A-PGJ-0052] 기일별 검색 목록 화면에서 상세 화면에서 목록화면으로 이동시 스크롤바 유지되도록 개선
 *  2025.12.26.   공태은       [25A-PGJ-0053] 나의경매 자주쓰는검색 화면에서 페이지 이동시 검색조건이 초기화되는 현상 수정
 * ============= ============ ==========================
 */
function moveCsDtlPage(index) {
    const csNo = dlt_srchResult.getCellData(index, 'saNo');
    const cortOfcCd = dlt_srchResult.getCellData(index, 'boCd');
    const dspslGdsSeq = dlt_srchResult.getCellData(index, 'maemulSer');
    const mvSaNo = dlt_srchResult.getCellData(index, 'mvSaNo');
    const srchInfo = dma_srchGdsDtlSrchInfo.getJSON();

    //상세 화면으로 이동시 목록화면의 스크롤 위치 정보를 저장
    const scrollTop = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop;
    srchInfo.srchRowIndex = scrollTop;

    if(scutilo.isEmpty(srchInfo.sideDvsCd)){
        srchInfo.sideDvsCd = '2';
    }

    srchInfo.menuNm = scwin.menuNm;
    const pgmId = scwin.pgmId;
    let obj = {
        "dataObject": { "type" : "json",
        "name" : "param",
        "data" : { csNo
            , cortOfcCd
            , dspslGdsSeq
            , mvSaNo
            , pgmId
            , prevInfo: { pageNum: dma_pageInfo.get('pageNo') }
            , srchInfo}
        }
    };
    $p.main().wfm_mainFrame.setSrc('/pgj/ui/pgj100/PGJ15BM04.xml',obj);
}

